const data = pm.response.json();

const category = pm.request.url.query.get("what");

const standardizedJobs = (data.results || []).map(job => ({
    job_id: job.id,
    title: job.title,
    company: job.company?.display_name || "Unknown",
    location: job.location?.display_name || "Unknown",
    url: job.redirect_url,
    source: "Adzuna",
    search_category: category,
    description: job.description || ""
}));

console.log("Standardized jobs:", standardizedJobs);

pm.environment.set(
    "latest_adzuna_jobs",
    JSON.stringify(standardizedJobs)
);


const existingJobs = JSON.parse(
    pm.environment.get("all_adzuna_jobs") || "[]"
);

const jobsById = new Map();

[...existingJobs, ...standardizedJobs].forEach(job => {
    const previous = jobsById.get(String(job.job_id));

    const categories = [
        ...(previous?.search_categories || 
            (previous?.search_category ? [previous.search_category] : [])),
        ...(job.search_categories || 
            (job.search_category ? [job.search_category] : []))
    ];

jobsById.set(String(job.job_id), {
    ...(previous || {}),
    ...job,
    description: job.description || previous?.description || "",
    search_categories: [...new Set(categories)]
});
});
const uniqueJobs = Array.from(jobsById.values());

pm.environment.set(
    "all_adzuna_jobs",
    JSON.stringify(uniqueJobs)
);

console.log("Total unique jobs stored:", uniqueJobs.length);

