const jobs = JSON.parse(
  pm.environment.get("all_adzuna_jobs") || "[]"
);

if (jobs.length === 0) {
  throw new Error("No Adzuna jobs found");
}

// STEP 1: Select the first Adzuna job
const job = jobs[0];

if (!job.job_id) {
  throw new Error("Job has no external ID");
}

const title = String(job.title || "").toLowerCase();
const description = String(job.description || "").toLowerCase();
const location = String(job.location || "").toLowerCase();

const jobText = title + " " + description;

// STEP 2: Define matching keywords
const processSkills = [
  "process management",
  "business process",
  "process improvement",
  "prozessoptimierung",
  "geschäftsprozessmanagement",
  "operational excellence",
  "continuous improvement",
  "wertstromanalyse",
  "kostensenkung"
];

const crmSkills = [
  "salesforce",
  "crm",
  "revenue operations",
  "sales operations",
  "sales automation",
  "marketing automation",
  "hubspot"
];

const preferredLocations = [
  "berlin",
  "hamburg"
];

const remoteKeywords = [
  "remote",
  "homeoffice",
  "home office",
  "fully remote"
];

const employmentKeywords = [
  "full-time",
  "full time",
  "vollzeit",
  "permanent",
  "unbefristet",
  "festanstellung"
];

const impactKeywords = [
  "nonprofit",
  "non-profit",
  "ngo",
  "sustainability",
  "nachhaltigkeit",
  "social impact",
  "humanitarian",
  "gemeinnützig"
];

// STEP 3: Check matches
const processMatch = processSkills.some(
  keyword => jobText.includes(keyword)
);

const crmMatch = crmSkills.some(
  keyword => jobText.includes(keyword)
);

const locationMatch =
  preferredLocations.some(
    keyword => location.includes(keyword)
  ) ||
  remoteKeywords.some(
    keyword => jobText.includes(keyword)
  );

const employmentMatch = employmentKeywords.some(
  keyword => description.includes(keyword)
);

const impactMatch = impactKeywords.some(
  keyword => jobText.includes(keyword)
);

// STEP 4: Calculate Fit Score
const skillScore =
  (processMatch ? 30 : 0) +
  (crmMatch ? 30 : 0);

const locationScore = locationMatch ? 20 : 0;
const employmentScore = employmentMatch ? 10 : 0;
const impactScore = impactMatch ? 10 : 0;

const fitScore =
  skillScore +
  locationScore +
  employmentScore +
  impactScore;

// STEP 5: Set External Job ID
pm.environment.set(
  "adzuna_job_id",
  String(job.job_id)
);

// STEP 6: Map Adzuna data to Salesforce
const salesforceJob = {
  Name: String(job.title || "Untitled Job").slice(0, 80),
  Company__c: String(job.company || "Unknown").slice(0, 255),
  Location__c: String(job.location || "Unknown").slice(0, 255),
  Job_URL__c: job.url || null,
  Source__c: "Adzuna",
  Fit_Score__c: fitScore
};

// STEP 7: Save JSON payload
pm.environment.set(
  "salesforce_job_payload",
  JSON.stringify(salesforceJob)
);

// STEP 8: Log results
console.log("Job:", job.title);
console.log("External Job ID:", job.job_id);
console.log("Process skills:", processMatch);
console.log("CRM skills:", crmMatch);
console.log("Location match:", locationMatch);
console.log("Employment match:", employmentMatch);
console.log("Impact match:", impactMatch);

console.log("Skill score:", skillScore, "/60");
console.log("Location score:", locationScore, "/20");
console.log("Employment score:", employmentScore, "/10");
console.log("Impact score:", impactScore, "/10");

console.log("FINAL FIT SCORE:", fitScore, "/100");
console.log("Salesforce payload:", salesforceJob);

const jobs = JSON.parse(
  pm.environment.get("all_adzuna_jobs") || "[]"
);

if (!jobs.length) {
  throw new Error("No Adzuna jobs found");
}

// STEP 1: Define two career paths
const careerPaths = {
  crm: {
    titles: [
      "salesforce administrator",
      "salesforce admin",
      "salesforce consultant",
      "salesforce product owner",
      "salesforce solution architect",
      "crm manager",
      "crm product owner",
      "technical crm",
      "revenue operations",
      "revops",
      "sales operations",
      "gtm engineer",
      "sales automation",
      "marketing automation",
      "application manager crm"
    ],
    skills: [
      "salesforce",
      "crm",
      "hubspot",
      "revenue operations",
      "sales operations",
      "sales automation",
      "marketing automation",
      "business analysis",
      "workflow automation",
      "data quality",
      "process mapping",
      "clay",
      "braze",
      "n8n"
    ]
  },

  process: {
    titles: [
      "operational excellence",
      "business improvement",
      "process improvement",
      "business process",
      "process manager",
      "process owner",
      "business transformation",
      "continuous improvement",
      "value chain",
      "value stream",
      "prozessoptimierung",
      "geschäftsprozessmanagement",
      "projektmanager prozess"
    ],
    skills: [
      "process improvement",
      "business process",
      "operational excellence",
      "continuous improvement",
      "value chain",
      "value stream",
      "process mapping",
      "cost reduction",
      "cost saving",
      "lean",
      "six sigma",
      "prozessoptimierung",
      "wertstromanalyse",
      "kostensenkung",
      "business transformation"
    ]
  }
};

// STEP 2: Define preferences
const remoteKeywords = [
  "remote",
  "homeoffice",
  "home office",
  "work from home",
  "mobiles arbeiten"
];

const employmentKeywords = [
  "permanent",
  "unbefristet",
  "festanstellung",
  "full-time",
  "full time",
  "vollzeit"
];

const impactKeywords = [
  "nonprofit",
  "non-profit",
  "ngo",
  "gemeinnützig",
  "sustainability",
  "nachhaltigkeit",
  "humanitarian",
  "social impact",
  "social enterprise"
];

// STEP 3: Helper function
function countMatches(text, keywords) {
  return keywords.filter(
    keyword => text.includes(keyword)
  ).length;
}

// STEP 4: Calculate Fit Score
function calculateFit(job) {
  const title = String(
    job.title || ""
  ).toLowerCase();

  const description = String(
    job.description || ""
  ).toLowerCase();

  const location = String(
    job.location || ""
  ).toLowerCase();

  const combined = title + " " + description;

  // Evaluate both career paths independently
  const pathScores = Object.entries(
    careerPaths
  ).map(([path, keywords]) => {

    const titleMatches = countMatches(
      title,
      keywords.titles
    );

    const skillMatches = countMatches(
      combined,
      keywords.skills
    );

    const titleScore = Math.min(
      titleMatches * 15,
      30
    );

    const skillScore = Math.min(
      skillMatches * 10,
      30
    );

    return {
      path: path,
      titleScore: titleScore,
      skillScore: skillScore,
      careerScore: titleScore + skillScore
    };
  });

  // Select the best career path
  pathScores.sort(
    (a, b) => b.careerScore - a.careerScore
  );

  const bestPath = pathScores[0];

  // STEP 5: Location score (20)
  const preferredCity =
    location.includes("berlin") ||
    location.includes("hamburg");

  const remoteMatch = remoteKeywords.some(
    keyword => combined.includes(keyword)
  );

  const locationScore =
    preferredCity || remoteMatch ? 20 : 0;

  // STEP 6: Employment score (10)
  const employmentMatch =
    employmentKeywords.some(
      keyword => description.includes(keyword)
    );

  const employmentScore =
    employmentMatch ? 10 : 0;

  // STEP 7: Impact score (10)
  const impactMatch =
    impactKeywords.some(
      keyword => combined.includes(keyword)
    );

  const impactScore =
    impactMatch ? 10 : 0;

  // STEP 8: Final score
  const fitScore =
    bestPath.careerScore +
    locationScore +
    employmentScore +
    impactScore;

  return {
    ...job,
    fit_score: fitScore,
    career_path: bestPath.path,
    score_breakdown: {
      title: bestPath.titleScore,
      skills: bestPath.skillScore,
      location: locationScore,
      employment: employmentScore,
      impact: impactScore
    }
  };
}

// STEP 9: Score all Adzuna jobs
const scoredJobs = jobs.map(
  job => calculateFit(job)
);

// STEP 10: Sort by highest Fit Score
scoredJobs.sort(
  (a, b) => b.fit_score - a.fit_score
);

// STEP 11: Save results to Postman
pm.environment.set(
  "scored_adzuna_jobs",
  JSON.stringify(scoredJobs)
);

// Reset import index
pm.environment.set(
  "job_import_index",
  "0"
);

// STEP 12: Display results
console.log(
  "Ranked jobs:",
  scoredJobs.map(job => ({
    title: job.title,
    company: job.company,
    location: job.location,
    career_path: job.career_path,
    fit_score: job.fit_score
  }))
);

console.log(
  "Total jobs scored:",
  scoredJobs.length
);

console.log(
  "Highest Fit Score:",
  scoredJobs[0]?.fit_score
);

console.log(
  "Scored jobs saved successfully!"
);

const jobs = JSON.parse(
  pm.environment.get("scored_adzuna_jobs") || "[]"
);

const index = Number(
  pm.environment.get("job_import_index") || "0"
);

if (jobs.length === 0) {
  throw new Error("No scored jobs found. Run request 13 first.");
}

if (index >= jobs.length) {
  throw new Error("All jobs have been processed.");
}

const job = jobs[index];

if (!job.job_id) {
  throw new Error("Missing External Job ID at index " + index);
}

// Set the external ID for Salesforce upsert
pm.environment.set(
  "adzuna_job_id",
  String(job.job_id)
);

// Build Salesforce payload
const payload = {
  Name: String(job.title || "Untitled Job").slice(0, 80),
  Company__c: String(job.company || "Unknown").slice(0, 255),
  Location__c: String(job.location || "Unknown").slice(0, 255),
  Job_URL__c: job.url || null,
  Source__c: "Adzuna",
  Fit_Score__c: job.fit_score
};

// Preserve existing Application Status
pm.environment.set(
  "salesforce_job_payload",
  JSON.stringify(payload)
);

console.log("Importing job:", index + 1, "of", jobs.length);
console.log("Job:", job.title);
console.log("Fit Score:", job.fit_score);

const jobs = JSON.parse(
  pm.environment.get("scored_adzuna_jobs") || "[]"
);

const index = Number(
  pm.environment.get("job_import_index") || "0"
);

const success = [200, 201, 204].includes(
  pm.response.code
);

if (success) {
  console.log(
    "SUCCESS: Imported job",
    index + 1,
    "of",
    jobs.length
  );

  pm.environment.set(
    "job_import_index",
    String(index + 1)
  );
} else {
  console.error(
    "IMPORT FAILED at job",
    index + 1
  );

  console.error(
    "Salesforce response:",
    pm.response.text()
  );

  pm.execution.setNextRequest(null);
}

/*
REQUEST 24 - BEFORE REQUEST
Select one RevOps job for Salesforce upsert.
*/

const raw = pm.environment.get("revops_final_import_jobs");

if (!raw) {
    throw new Error("Missing revops_final_import_jobs");
}

const jobs = JSON.parse(raw);

if (!Array.isArray(jobs) || jobs.length === 0) {
    throw new Error("No jobs prepared for import");
}

const index = Number(
    pm.environment.get("revops_import_index") || 0
);

if (!Number.isInteger(index) ||
    index < 0 ||
    index >= jobs.length) {
    throw new Error(
        "Invalid import index: " + index +
        ". Expected 0 to " + (jobs.length - 1)
    );
}

const job = jobs[index];

if (!job.external_id || !job.payload) {
    throw new Error(
        "Missing external ID or payload at index " + index
    );
}

// Preserve prepared payload without changing application status.
const payload = { ...job.payload };
delete payload.Application_Status__c;

// Validate required fields.
if (!payload.Name ||
    !payload.Company__c ||
    !payload.Job_URL__c) {
    throw new Error(
        "Missing required job fields at index " + index
    );
}

if (payload.Name.length > 80) {
    throw new Error("Job title exceeds 80 characters");
}

pm.variables.set("revops_job_id", job.external_id);

pm.variables.set(
    "revops_salesforce_payload",
    JSON.stringify(payload)
);

pm.variables.set(
    "revops_current_import_index",
    String(index)
);

console.log(
    "IMPORTING:",
    index + 1,
    "/",
    jobs.length,
    payload.Name
);

console.log("Company:", payload.Company__c);
console.log("External ID:", job.external_id);

/*
REQUEST 24 - AFTER RESPONSE

Advance only after a successful Salesforce upsert.
Successful responses: 200, 201 or 204.
*/

const status = pm.response.code;

const index = Number(
    pm.variables.get("revops_current_import_index")
);

const jobs = JSON.parse(
    pm.environment.get("revops_final_import_jobs")
);

const success = [200, 201, 204].includes(status);

pm.test("Salesforce upsert successful", function () {
    pm.expect(
        status,
        pm.response.text()
    ).to.be.oneOf([200, 201, 204]);
});

if (success) {
    const nextIndex = index + 1;

    pm.environment.set(
        "revops_import_index",
        String(nextIndex)
    );

    console.log(
        "SUCCESS:",
        nextIndex,
        "/",
        jobs.length,
        "HTTP",
        status
    );

    if (nextIndex === jobs.length) {
        console.log("ALL REVOPS JOBS IMPORTED");
    }

} else {
    console.error(
        "SALESFORCE IMPORT FAILED"
    );

    console.error("HTTP status:", status);
    console.error(
        "Response:",
        pm.response.text()
    );

    console.error(
        "Failed job index:",
        index
    );

    console.error(
        "Import stopped. Index not advanced."
    );

    pm.execution.setNextRequest(null);
}

/*
REVOPS CAREERS - GERMANY JOB FILTER
Request 15 - After response

Reads RSS XML, converts to JSON,
filters Germany-relevant vacancies,
and saves results in Postman.
*/

const xml2js = require("xml2js");

pm.test("HTTP 200", function () {
    pm.response.to.have.status(200);
});

const xml = pm.response.text();

pm.test("Valid RSS response", function () {
    pm.expect(xml).to.include("<rss");
});

// Convert XML into a JavaScript object
const parser = new xml2js.Parser({
    explicitArray: false,
    trim: true
});

parser.parseString(xml, function (error, parsed) {

    if (error) {
        console.error("XML parsing failed:", error);
        pm.test("XML parsing succeeded", function () {
            throw error;
        });
        return;
    }

    const channel = parsed.rss.channel;
    const rawItems = channel.item || [];

    const jobs = Array.isArray(rawItems)
        ? rawItems
        : [rawItems];

    // Extract text safely
    function getText(value) {
        if (typeof value === "string") {
            return value.trim();
        }

        if (typeof value === "number") {
            return String(value);
        }

        if (value && typeof value === "object") {
            return String(value._ || "").trim();
        }

        return "";
    }

    // Convert jobs to standard JSON records
    const allJobs = jobs.map(job => ({
        id: getText(job.guid) || getText(job.link),
        title: getText(job.title),
        company: getText(job["job_listing:company"]),
        location: getText(job["job_listing:location"]),
        job_type: getText(job["job_listing:job_type"]),
        category: getText(job["job_listing:job_category"]),
        description: getText(job.description),
        url: getText(job.link),
        published: getText(job.pubDate),
        source: "RevOps Careers"
    }));

    // Identify Germany-relevant jobs
    function classifyLocation(job) {
        const location = job.location.toLowerCase();
        const type = job.job_type.toLowerCase();

        const germany =
            /\b(germany|deutschland|berlin|hamburg|munich|münchen|frankfurt|cologne|köln|düsseldorf|stuttgart|leipzig|bonn|hannover)\b/i;

        const europe =
            /\b(europe|emea|european union|eu-wide)\b/i;

        const remote = type.includes("remote") ||
            /\bremote\b/i.test(location);

        if (germany.test(location)) {
            return {
                match: true,
                reason: "Germany location"
            };
        }

        if (remote && europe.test(location)) {
            return {
                match: true,
                reason: "Remote Europe/EMEA - verify eligibility"
            };
        }

        return {
            match: false,
            reason: "Outside target geography"
        };
    }

    const filteredJobs = allJobs
        .map(job => {
            const result = classifyLocation(job);

            return {
                ...job,
                location_match: result.reason,
                is_relevant_location: result.match
            };
        })
        .filter(job => job.is_relevant_location);

    // Save results in Postman environment
    pm.environment.set(
        "revops_all_jobs",
        JSON.stringify(allJobs)
    );

    pm.environment.set(
        "revops_filtered_jobs",
        JSON.stringify(filteredJobs)
    );

