/*
REQUEST 19
REVOPS CAREERS - PREPARE & SCORE JOBS

Input:
  revops_germany_jobs

Output:
  revops_scored_jobs
  revops_salesforce_ready
  revops_review_jobs
  revops_preparation_summary

Does NOT write to Salesforce.
*/

const raw = pm.environment.get("revops_germany_jobs");

if (!raw) {
    throw new Error(
        "Missing revops_germany_jobs. Run requests 16, 17 and 18 first."
    );
}

let sourceJobs;

try {
    sourceJobs = JSON.parse(raw);
} catch (e) {
    throw new Error("RevOps jobs contain invalid JSON.");
}

if (!Array.isArray(sourceJobs) || sourceJobs.length === 0) {
    throw new Error("No RevOps jobs available.");
}

// ---------- HELPERS ----------

function clean(value) {
    return String(value || "")
        .replace(/<[^>]*>/g, " ")
        .replace(/&amp;|&#038;/gi, "&")
        .replace(/&nbsp;/gi, " ")
        .replace(/\s+/g, " ")
        .trim();
}

function normalized(value) {
    return clean(value)
        .toLowerCase()
        .normalize("NFKD")
        .replace(/[\u0300-\u036f]/g, "");
}

function containsAny(text, terms) {
    return terms.some(term =>
        text.includes(normalized(term))
    );
}

function countMatches(text, terms) {
    return terms.filter(term =>
        text.includes(normalized(term))
    ).length;
}

// ---------- CAREER PATHS ----------

const paths = [
    {
        name: "CRM / RevOps / Salesforce",
        titles: [
            "revenue operations",
            "revops",
            "sales operations",
            "salesforce",
            "crm manager",
            "crm administrator",
            "crm product owner",
            "gtm engineer",
            "go-to-market operations",
            "sales automation",
            "business systems",
            "marketing operations",
            "customer operations"
        ],
        skills: [
            "salesforce",
            "hubspot",
            "crm",
            "workflow",
            "automation",
            "integration",
            "api",
            "reporting",
            "dashboard",
            "data quality",
            "sales operations",
            "revenue operations",
            "process improvement",
            "requirements",
            "stakeholder",
            "postman"
        ]
    },
    {
        name: "Business Improvement / Operational Excellence",
        titles: [
            "operational excellence",
            "business improvement",
            "process improvement",
            "business process",
            "business transformation",
            "continuous improvement",
            "process manager",
            "business analyst",
            "value chain",
            "process optimization",
            "prozessoptimierung",
            "geschaftsprozessmanagement"
        ],
        skills: [
            "process mapping",
            "bpmn",
            "continuous improvement",
            "lean",
            "operational excellence",
            "cost reduction",
            "cost saving",
            "value chain",
            "business analysis",
            "process optimization",
            "prozessoptimierung",
            "wertstromanalyse",
            "kostensenkung",
            "sap",
            "stakeholder",
            "reporting"
        ]
    }
];

// ---------- LOCATION ----------

function classifyLocation(job) {
    const location = normalized(job.location);
    const type = normalized(job.job_type);

    const germany =
        /\b(germany|deutschland|berlin|hamburg|munich|munchen|frankfurt|cologne|koln|dusseldorf|stuttgart|leipzig|bonn|hannover|bremen|dresden|potsdam)\b/;

    const europe =
        /\b(europe|emea|european union|eu-wide)\b/;

    const isRemote =
        /\bremote\b/.test(type + " " + location);

    if (/\bberlin\b/.test(location)) {
        return {
            eligible: true,
            category: "Berlin",
            points: 20,
            verified: true
        };
    }

    if (/\bhamburg\b/.test(location)) {
        return {
            eligible: true,
            category: "Hamburg",
            points: 20,
            verified: true
        };
    }

    if (germany.test(location)) {
        return {
            eligible: true,
            category: "Germany",
            points: 12,
            verified: true
        };
    }

    if (isRemote && europe.test(location)) {
        return {
            eligible: true,
            category: "Remote Europe/EMEA",
            points: 12,
            verified: false
        };
    }

    return {
        eligible: false,
        category: "Outside target geography",
        points: 0,
        verified: false
    };
}

// ---------- FIT SCORING ----------

function scoreJob(job) {
    const title = normalized(job.title);
    const description = normalized(job.description);
    const combined = title + " " + description;

    const location = classifyLocation(job);

    const pathScores = paths.map(path => {
        const titleMatches =
            countMatches(title, path.titles);

        const skillMatches =
            countMatches(combined, path.skills);

        const titlePoints =
            Math.min(30, titleMatches * 15);

        const skillPoints =
            Math.min(30, skillMatches * 5);

        return {
            path: path.name,
            titlePoints,
            skillPoints,
            combined: titlePoints + skillPoints
        };
    });

    pathScores.sort((a, b) =>
        b.combined - a.combined
    );

    const best = pathScores[0];

    // Employment type: up to 10 points
    const type = normalized(job.job_type);

    let employmentPoints = 0;

    if (type.includes("full time")) {
        employmentPoints = 10;
    } else if (type.includes("part time")) {
        employmentPoints = 7;
    }

    // Impact / nonprofit: up to 10 points
    const impactTerms = [
        "nonprofit",
        "non-profit",
        "ngo",
        "foundation",
        "charity",
        "humanitarian",
        "sustainability",
        "social impact",
        "gemeinnutzig"
    ];

    const impactPoints =
        containsAny(combined, impactTerms) ? 10 : 0;

    const score = Math.min(
        100,
        best.combined +
        location.points +
        employmentPoints +
        impactPoints
    );

    return {
        score,
        career_path: best.path,
        title_points: best.titlePoints,
        skills_points: best.skillPoints,
        location_points: location.points,
        employment_points: employmentPoints,
        impact_points: impactPoints,
        location_category: location.category,
        location_verified: location.verified,
        location_eligible: location.eligible
    };
}

// ---------- NORMALIZE ----------

const normalizedJobs = sourceJobs.map(job => {
    const result = {
        id: clean(job.id || job.url),
        title: clean(job.title),
        company: clean(job.company),
        location: clean(job.location),
        job_type: clean(job.job_type),
        category: clean(job.category),
        description: clean(job.description),
        url: clean(job.url),
        published: clean(job.published),
        source: "RevOps Careers"
    };

    return {
        ...result,
        ...scoreJob(result)
    };
});

// ---------- DEDUPLICATE ----------

const uniqueMap = new Map();

normalizedJobs.forEach(job => {
    if (job.id) {
        uniqueMap.set(job.id, job);
    }
});

const uniqueJobs = Array.from(uniqueMap.values());

// ---------- QUALITY CHECKS ----------

const prepared = uniqueJobs.map(job => {
    const issues = [];

    if (!job.title) issues.push("Missing title");
    if (!job.company) issues.push("Missing company");
    if (!job.url) issues.push("Missing URL");
    if (!job.location) issues.push("Missing location");
    if (!job.description) {
        issues.push("Missing description");
    }

    if (!job.location_eligible) {
        issues.push("Location not eligible");
    }

    if (!job.location_verified) {
        issues.push("Verify remote Germany eligibility");
    }

    if (job.score < 40) {
        issues.push("Low fit score");
    }

    return {
        ...job,
        quality_issues: issues,
        needs_review: issues.length > 0
    };
});

// ---------- PREPARE SALESFORCE ----------

// Existing Salesforce object fields only.
// Application_Status__c intentionally excluded.

const salesforceReady = prepared
    .filter(job =>
        job.location_eligible &&
        job.title &&
        job.company &&
        job.url &&
        job.location_verified &&
        job.score >= 40
    )
    .map(job => ({
        external_id: "REVOPS:" + job.id,
        payload: {
            Name: job.title.substring(0, 80),
            Company__c: job.company,
            Location__c: job.location,
            Job_URL__c: job.url,
            Source__c: "RevOps Careers",
            Fit_Score__c: job.score
        },
        career_path: job.career_path,
        original_url: job.url,
        description: job.description,
        fit_score: job.score
    }));

const reviewJobs = prepared.filter(job =>
    job.needs_review
);

// ---------- SAVE ----------

pm.environment.set(
    "revops_scored_jobs",
    JSON.stringify(prepared)
);

pm.environment.set(
    "revops_salesforce_ready",
    JSON.stringify(salesforceReady)
);

pm.environment.set(
    "revops_review_jobs",
    JSON.stringify(reviewJobs)
);

const summary = {
    input_jobs: sourceJobs.length,
    unique_jobs: uniqueJobs.length,
    salesforce_ready: salesforceReady.length,
    review_jobs: reviewJobs.length,
    highest_score: Math.max(
        ...prepared.map(job => job.score)
    ),
    berlin: prepared.filter(
        job => job.location_category === "Berlin"
    ).length,
    hamburg: prepared.filter(
        job => job.location_category === "Hamburg"
    ).length,
    germany_other: prepared.filter(
        job => job.location_category === "Germany"
    ).length,
    remote_emea_review: prepared.filter(
        job => job.location_category === "Remote Europe/EMEA"
    ).length
};

pm.environment.set(
    "revops_preparation_summary",
    JSON.stringify(summary)
);

// ---------- CONSOLE ----------

console.log("================================");
console.log("REVOPS CAREERS - PREPARATION");
console.log("================================");

console.log("Input jobs:", summary.input_jobs);
console.log("Unique jobs:", summary.unique_jobs);
console.log("Salesforce ready:", summary.salesforce_ready);
console.log("Review jobs:", summary.review_jobs);
console.log("Highest score:", summary.highest_score);

console.log("Berlin:", summary.berlin);
console.log("Hamburg:", summary.hamburg);
console.log("Other Germany:", summary.germany_other);
console.log(
    "Remote EMEA needing verification:",
    summary.remote_emea_review
);

console.log("TOP 15 JOBS:");

prepared
    .slice()
    .sort((a, b) => b.score - a.score)
    .slice(0, 15)
    .forEach((job, i) => {
        console.log(
            (i + 1) + ". " +
            job.score + "/100 | " +
            job.title + " | " +
            job.company + " | " +
            job.location
        );
    });

console.log("PREPARATION COMPLETE");

/*
REQUEST 20
REVOPS CAREERS - VALIDATE SALESFORCE IMPORT

Input:
  revops_salesforce_ready
  scored_adzuna_jobs

Output:
  revops_final_import_jobs
  revops_cross_source_duplicates
  revops_import_summary

No Salesforce writes.
No employment-level exclusions.
*/

function readArray(name, required = false) {
    const raw = pm.environment.get(name);

    if (!raw) {
        if (required) {
            throw new Error("Missing variable: " + name);
        }
        return [];
    }

    const parsed = JSON.parse(raw);

    if (!Array.isArray(parsed)) {
        throw new Error(name + " must be an array.");
    }

    return parsed;
}

