// Normalize text for duplicate comparisons
function normalize(value) {
    return String(value || "")
        .toLowerCase()
        .normalize("NFKD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/&amp;|&#038;/gi, "&")
        .replace(/[^a-z0-9]+/g, " ")
        .replace(/\s+/g, " ")
        .trim();
}

function jobIdentity(job) {
    const p = job.payload || job;

    return {
        title: normalize(
            p.Name || job.title
        ),
        company: normalize(
            p.Company__c ||
            job.company ||
            job.company_name
        ),
        location: normalize(
            p.Location__c || job.location
        )
    };
}

// Build Adzuna comparison keys
const adzunaKeys = new Set();

adzuna.forEach(job => {
    const identity = jobIdentity(job);

    if (identity.title && identity.company) {
        adzunaKeys.add(
            identity.company + "|" +
            identity.title
        );
    }
});

// Short deterministic hash
// FNV-1a, two independent passes
function hash32(value, seed) {
    let hash = seed >>> 0;

    for (let i = 0; i < value.length; i++) {
        hash ^= value.charCodeAt(i);
        hash = Math.imul(hash, 16777619);
    }

    return (hash >>> 0)
        .toString(16)
        .padStart(8, "0");
}

function makeExternalId(url) {
    const value = String(url || "");

    return "REVOPS-" +
        hash32(value, 2166136261) +
        hash32(value, 2246822519);
}

const duplicates = [];
const candidates = [];
const seenIds = new Set();

revops.forEach(job => {
    const identity = jobIdentity(job);

    const key =
        identity.company + "|" +
        identity.title;

    if (adzunaKeys.has(key)) {
        duplicates.push({
            reason: "Company + title matches Adzuna",
            title: job.payload.Name,
            company: job.payload.Company__c,
            source_url: job.original_url
        });
        return;
    }

    const externalId = makeExternalId(
        job.original_url
    );

    if (seenIds.has(externalId)) {
        duplicates.push({
            reason: "Duplicate RevOps external ID",
            title: job.payload.Name,
            company: job.payload.Company__c
        });
        return;
    }

    seenIds.add(externalId);

    candidates.push({
        external_id: externalId,
        payload: {
            ...job.payload,
            Source__c: "RevOps Careers"
        },
        fit_score: job.fit_score,
        career_path: job.career_path,
