// Read searchable text
function jobText(job) {
    const p = job.payload || job;

    return [
        job.title || p.Name || "",
        job.description || "",
        job.category || "",
        job.job_type || ""
    ].join(" ");
}

// Extract skills from a job
function extractSkills(job) {
    const text = jobText(job);
    const found = [];

    Object.keys(skills).forEach(category => {
        Object.entries(skills[category]).forEach(
            ([skill, pattern]) => {
                if (pattern.test(text)) {
                    found.push({
                        skill,
                        category
                    });
                }
            }
        );
    });

    return found;
}

// Analyze one dataset
function analyze(jobs, label) {
    const counts = {};
    const pairs = {};
    const jobResults = [];

    jobs.forEach(job => {
        const matches = extractSkills(job);
        const names = [...new Set(
            matches.map(m => m.skill)
        )].sort();

        names.forEach(name => {
            counts[name] = (counts[name] || 0) + 1;
        });

        // Count technology combinations
        for (let i = 0; i < names.length; i++) {
            for (let j = i + 1; j < names.length; j++) {
                const key = names[i] + " + " + names[j];
                pairs[key] = (pairs[key] || 0) + 1;
            }
        }

        const p = job.payload || job;

        jobResults.push({
            title: job.title || p.Name || "",
            company: job.company || p.Company__c || "",
            fit_score: job.score || job.fit_score || 0,
            skills: names,
            source_url: job.url || job.source_url || ""
        });
    });

    const ranking = Object.entries(counts)
        .map(([skill, count]) => ({
            skill,
            count,
            percentage: jobs.length
                ? Number(
                    (count / jobs.length * 100).toFixed(1)
                )
                : 0
        }))
        .sort((a, b) => b.count - a.count);

    const combinations = Object.entries(pairs)
        .map(([pair, count]) => ({
            pair,
            count
        }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 20);

    return {
        label,
        total_jobs: jobs.length,
        ranking,
        combinations,
        job_results: jobResults
    };
}

