// Count how many jobs mention each skill
function buildRanking(field) {
    const counts = {};
    const jobExamples = {};

    jobs.forEach(job => {
        const values = Array.isArray(job[field])
            ? [...new Set(job[field])]
            : [];

        values.forEach(skill => {
            counts[skill] = (counts[skill] || 0) + 1;

            if (!jobExamples[skill]) {
                jobExamples[skill] = [];
            }

            jobExamples[skill].push({
                title: job.title,
                company: job.company,
                fit_score: job.fit_score,
                url: job.source_url
            });
        });
    });

    return Object.entries(counts)
        .map(([skill, count]) => ({
            skill,
            jobs: count,
            percentage: Number(
                (count / jobs.length * 100).toFixed(1)
            ),
            examples: jobExamples[skill]
                .sort(
                    (a, b) =>
                        (b.fit_score || 0) -
                        (a.fit_score || 0)
                )
                .slice(0, 5)
        }))
        .sort(
            (a, b) =>
                b.jobs - a.jobs ||
                a.skill.localeCompare(b.skill)
        );
}

